sys_script_include.script:
var ProductModelFilter = Class.create();
ProductModelFilter.prototype = {
    initialize: function() {},

    getModelsForCurrentUser: function() {

        var user = gs.getUserID();
        var grAsset = new GlideRecord('alm_asset');
        var models = [];

        grAsset.addQuery('owned_by', user);
        grAsset.query();

        while (grAsset.next()) {
            var id = grAsset.model_category.sys_id.toString();
            if (models.indexOf(id) === (-1)) {
                models.push(id);
            }
        }
        return 'sys_idIN' + models.join(',');
    },

    type: 'ProductModelFilter'
};
